// Regenerates the typed client from the server's OpenAPI document.
// The server's Pydantic models are the source of truth; never edit the generated files.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const server = join(root, "..", "..", "apps", "server");
const specPath = join(root, "src", "openapi.json");
const clientPath = join(root, "src", "KittumApi.gen.ts");

const spec = execFileSync("uv", ["run", "--directory", server, "kittum", "openapi"], {
  encoding: "utf8",
});
writeFileSync(specPath, spec);

const client = execFileSync("openapigen", ["--spec", specPath, "--name", "KittumApi"], {
  encoding: "utf8",
});
writeFileSync(clientPath, `// Generated by scripts/generate.ts. Do not edit.\n${client}`);
